<?php
namespace App\Http\Controllers\Admin;
use App\Actions\Payment\SavePaymentAccountAction; use App\Http\Controllers\Controller; use App\Http\Requests\StorePaymentAccountRequest; use App\Models\PaymentAccount; use Illuminate\Http\JsonResponse;
class PaymentAccountController extends Controller { public function index(): JsonResponse { $room=request()->attributes->get('room'); return response()->json(['data'=>$room->paymentAccounts()->paginate(20)]); } public function store(StorePaymentAccountRequest $request,SavePaymentAccountAction $action): JsonResponse { return response()->json(['data'=>$action->execute(request()->attributes->get('room'),$request->validated(),null)],201); } public function update(StorePaymentAccountRequest $request,PaymentAccount $account,SavePaymentAccountAction $action): JsonResponse { abort_unless($account->room_id===request()->attributes->get('room')->id,404); return response()->json(['data'=>$action->execute(request()->attributes->get('room'),$request->validated(),$account)]); } }
